"""matplotlib.dates — date handling for matplotlib."""

import numpy as _np
from matplotlib.ticker import Locator, Formatter

# Epoch: days since 0001-01-01 UTC + 1 (matplotlib convention)
EPOCH_OFFSET = 719163  # days from 0001-01-01 to 1970-01-01

MICROSECONDLY = 0
SECONDLY = 1
MINUTELY = 2
HOURLY = 3
DAILY = 4
WEEKLY = 5
MONTHLY = 6
YEARLY = 7

MO, TU, WE, TH, FR, SA, SU = range(7)


def date2num(d):
    """Convert datetime → matplotlib float date (days since 0001-01-01 UTC).

    Treats *naive* datetimes as UTC (mirroring upstream's behaviour) —
    this gives an exact roundtrip with :func:`num2date`. Using
    ``d.timestamp()`` would interpret naive datetimes as *local* time
    which then offsets the result by the system timezone when num2date
    converts back from UTC.
    """
    import datetime as _dt
    if hasattr(d, '__iter__') and not isinstance(d, str):
        return _np.array([date2num(di) for di in d])
    if isinstance(d, _dt.datetime):
        if d.tzinfo is not None:
            # tz-aware: convert to UTC first.
            d = d.astimezone(_dt.timezone.utc).replace(tzinfo=None)
        delta = d - _dt.datetime(1970, 1, 1)
        return delta.total_seconds() / 86400.0 + EPOCH_OFFSET
    if isinstance(d, _dt.date):
        delta = _dt.datetime(d.year, d.month, d.day) - _dt.datetime(1970, 1, 1)
        return delta.total_seconds() / 86400.0 + EPOCH_OFFSET
    return float(d)


def num2date(x, tz=None):
    """Convert matplotlib float date → datetime (UTC-naive by default,
    or in ``tz`` when provided)."""
    import datetime as _dt
    if hasattr(x, '__iter__'):
        return [num2date(xi, tz) for xi in x]
    days = float(x) - EPOCH_OFFSET
    dt = _dt.datetime(1970, 1, 1) + _dt.timedelta(days=days)
    if tz is not None:
        dt = dt.replace(tzinfo=_dt.timezone.utc).astimezone(tz)
    return dt


def datestr2num(d, default=None):
    """Convert date string to number."""
    import datetime
    try:
        dt = datetime.datetime.fromisoformat(str(d))
        return date2num(dt)
    except (ValueError, TypeError):
        return 0.0


def num2timedelta(x):
    import datetime
    return datetime.timedelta(days=x)


def drange(dstart, dend, delta):
    """Return a sequence of equally spaced dates."""
    f1 = date2num(dstart)
    f2 = date2num(dend)
    step = delta.total_seconds() / 86400.0
    return _np.arange(f1, f2, step)


def epoch2num(e):
    return _np.asarray(e) / 86400.0 + EPOCH_OFFSET


def num2epoch(d):
    return (d - EPOCH_OFFSET) * 86400.0


def set_epoch(epoch):
    pass


def get_epoch():
    return '1970-01-01T00:00:00'


# ── Locators ────────────────────────────────────────────────────

class DateLocator(Locator):
    """Base for all date locators. Subclasses implement ``tick_values``
    by walking calendar periods between the requested vmin/vmax."""

    def __init__(self, tz=None):
        self.tz = tz

    def datalim_to_dt(self):
        """Return ``(vmin, vmax)`` of the axis's data interval as
        ``datetime`` instances. Falls back to (None, None) when no
        axis is registered."""
        if self.axis is None:
            return (None, None)
        try:
            lo, hi = self.axis.get_data_interval()
            return num2date(lo, self.tz), num2date(hi, self.tz)
        except Exception:
            return (None, None)

    def viewlim_to_dt(self):
        if self.axis is None:
            return (None, None)
        try:
            lo, hi = self.axis.get_view_interval()
            return num2date(lo, self.tz), num2date(hi, self.tz)
        except Exception:
            return (None, None)


class AutoDateLocator(DateLocator):
    """Pick whichever date locator family produces ``minticks ≤ N ≤ maxticks``
    ticks for the requested interval. Walks year/month/day/hour cascade."""

    def __init__(self, tz=None, minticks=5, maxticks=None, interval_multiples=True):
        super().__init__(tz)
        self.minticks = minticks
        self.maxticks = maxticks or 11
        self.interval_multiples = interval_multiples

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            return []
        # Choose granularity based on span (in days).
        span = float(vmax) - float(vmin)
        if span <= 0:
            return [float(vmin)]
        if span > 365 * 2:
            # Multi-year — yearly ticks.
            interval = max(1, int(_np.ceil(span / 365 / self.maxticks)))
            return YearLocator(base=interval, tz=self.tz).tick_values(vmin, vmax)
        if span > 30:
            interval = max(1, int(_np.ceil(span / 30 / self.maxticks)))
            return MonthLocator(interval=interval, tz=self.tz).tick_values(vmin, vmax)
        if span > 1:
            interval = max(1, int(_np.ceil(span / self.maxticks)))
            return DayLocator(interval=interval, tz=self.tz).tick_values(vmin, vmax)
        if span > 1 / 24:
            interval = max(1, int(_np.ceil(24 * span / self.maxticks)))
            return HourLocator(interval=interval, tz=self.tz).tick_values(vmin, vmax)
        # Sub-hour.
        interval = max(1, int(_np.ceil(24 * 60 * span / self.maxticks)))
        return MinuteLocator(interval=interval, tz=self.tz).tick_values(vmin, vmax)


class YearLocator(DateLocator):
    """Tick at the same month+day every ``base`` years."""

    def __init__(self, base=1, month=1, day=1, tz=None):
        super().__init__(tz)
        self.base = int(base)
        self.month = int(month)
        self.day = int(day)

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        y0 = dmin.year - (dmin.year % self.base)
        ticks = []
        y = y0
        while True:
            try:
                d = _dt.datetime(y, self.month, self.day,
                                  tzinfo=dmin.tzinfo if hasattr(dmin, 'tzinfo') else None)
            except ValueError:
                y += self.base; continue
            v = date2num(d)
            if v > vmax: break
            if v >= vmin: ticks.append(v)
            y += self.base
            if y > dmax.year + self.base: break
        return ticks


class MonthLocator(DateLocator):
    """Tick on the ``bymonthday``-th of every ``interval`` month."""

    def __init__(self, bymonth=None, bymonthday=1, interval=1, tz=None):
        super().__init__(tz)
        self.bymonth = bymonth if bymonth is not None else list(range(1, 13))
        if isinstance(self.bymonth, int):
            self.bymonth = [self.bymonth]
        self.bymonthday = int(bymonthday)
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        ticks = []
        y, m = dmin.year, 1
        while True:
            if (m - 1) % self.interval == 0 and m in self.bymonth:
                try:
                    d = _dt.datetime(y, m, self.bymonthday)
                except ValueError:
                    m += 1
                    if m > 12: y += 1; m = 1
                    continue
                v = date2num(d)
                if v > vmax: break
                if v >= vmin: ticks.append(v)
            m += 1
            if m > 12: y += 1; m = 1
            if y > dmax.year + 1: break
        return ticks


class WeekdayLocator(DateLocator):
    """Tick on every occurrence of ``byweekday`` (0=Monday)."""

    def __init__(self, byweekday=0, interval=1, tz=None):
        super().__init__(tz)
        self.byweekday = byweekday
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        # Find the first matching weekday at-or-after dmin.
        wanted = (self.byweekday if isinstance(self.byweekday, int)
                  else self.byweekday[0])
        delta_days = (wanted - dmin.weekday()) % 7
        cur = _dt.datetime(dmin.year, dmin.month, dmin.day) + _dt.timedelta(days=delta_days)
        ticks = []
        step = _dt.timedelta(days=7 * self.interval)
        while cur <= dmax:
            v = date2num(cur)
            if v >= vmin: ticks.append(v)
            cur += step
        return ticks


class DayLocator(DateLocator):
    """Tick on the ``bymonthday``-th of every month (or every day)."""

    def __init__(self, bymonthday=None, interval=1, tz=None):
        super().__init__(tz)
        self.bymonthday = bymonthday
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        cur = _dt.datetime(dmin.year, dmin.month, dmin.day)
        ticks = []
        step = _dt.timedelta(days=self.interval)
        while cur <= dmax:
            if self.bymonthday is None or cur.day == self.bymonthday or \
               (hasattr(self.bymonthday, '__iter__') and cur.day in self.bymonthday):
                v = date2num(cur)
                if v >= vmin: ticks.append(v)
            cur += step
        return ticks


class HourLocator(DateLocator):
    def __init__(self, byhour=None, interval=1, tz=None):
        super().__init__(tz)
        self.byhour = byhour
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        cur = _dt.datetime(dmin.year, dmin.month, dmin.day, dmin.hour)
        ticks = []
        step = _dt.timedelta(hours=self.interval)
        while cur <= dmax:
            if self.byhour is None or cur.hour == self.byhour or \
               (hasattr(self.byhour, '__iter__') and cur.hour in self.byhour):
                v = date2num(cur)
                if v >= vmin: ticks.append(v)
            cur += step
        return ticks


class MinuteLocator(DateLocator):
    def __init__(self, byminute=None, interval=1, tz=None):
        super().__init__(tz)
        self.byminute = byminute
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        cur = _dt.datetime(dmin.year, dmin.month, dmin.day,
                            dmin.hour, dmin.minute)
        ticks = []
        step = _dt.timedelta(minutes=self.interval)
        while cur <= dmax:
            v = date2num(cur)
            if v >= vmin: ticks.append(v)
            cur += step
        return ticks


class SecondLocator(DateLocator):
    def __init__(self, bysecond=None, interval=1, tz=None):
        super().__init__(tz)
        self.bysecond = bysecond
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        import datetime as _dt
        if vmin is None or vmax is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        cur = _dt.datetime(dmin.year, dmin.month, dmin.day,
                            dmin.hour, dmin.minute, dmin.second)
        ticks = []
        step = _dt.timedelta(seconds=self.interval)
        while cur <= dmax:
            v = date2num(cur)
            if v >= vmin: ticks.append(v)
            cur += step
        return ticks


class MicrosecondLocator(DateLocator):
    def __init__(self, interval=1, tz=None):
        super().__init__(tz)
        self.interval = max(1, int(interval))

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None: return []
        # Microsecond ticks — emit a uniform stride.
        step = self.interval / 1e6 / 86400.0
        n_max = 1000  # safety cap
        n = min(n_max, max(1, int((vmax - vmin) / step)))
        return [vmin + i * step for i in range(n + 1) if vmin + i * step <= vmax]


class RRuleLocator(DateLocator):
    """Tick by a dateutil ``rrule`` (recurrence rule)."""

    def __init__(self, o, tz=None):
        super().__init__(tz)
        self.rule = o

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None or self.rule is None:
            return []
        dmin = num2date(vmin); dmax = num2date(vmax)
        try:
            return [date2num(d) for d in self.rule.between(dmin, dmax, inc=True)]
        except Exception:
            return []


# ── Formatters ──────────────────────────────────────────────────

class DateFormatter(Formatter):
    def __init__(self, fmt, tz=None, *, usetex=None):
        self.fmt = fmt
        self.tz = tz

    def __call__(self, x, pos=None):
        try:
            dt = num2date(x)
            return dt.strftime(self.fmt)
        except Exception:
            return str(x)


class AutoDateFormatter(Formatter):
    def __init__(self, locator, tz=None, defaultfmt='%Y-%m-%d'):
        self.locator = locator
        self.defaultfmt = defaultfmt

    def __call__(self, x, pos=None):
        try:
            dt = num2date(x)
            return dt.strftime(self.defaultfmt)
        except Exception:
            return str(x)


class ConciseDateFormatter(AutoDateFormatter):
    def __init__(self, locator, tz=None, formats=None, zero_formats=None,
                 offset_formats=None, show_offset=True, *, usetex=None):
        super().__init__(locator, tz)


class DateConverter:
    pass


# ─── Added: missing public names from upstream dates.py ────────────


class IndexDateFormatter(Formatter):
    """Format an *index* (integer position) into a date by looking up the
    Nth date in a fixed list. Useful when the x-data are plotted at
    integer positions but should be labelled with dates."""

    def __init__(self, t, fmt, tz=None):
        self.t = list(t)
        self.fmt = fmt
        self.tz = tz

    def __call__(self, x, pos=None):
        try:
            idx = int(round(x))
            if 0 <= idx < len(self.t):
                return num2date(self.t[idx]).strftime(self.fmt)
        except Exception:
            pass
        return ''


class ConciseDateConverter(DateConverter):
    """Variant of :class:`DateConverter` that emits more compact tick
    labels (delegated to :class:`ConciseDateFormatter`). The shim
    inherits the parent class wholesale — the formatter is the part
    callers actually consume."""
    pass


def _from_ordinalf(x, tz=None):
    """Convert an *ordinal* (days-since-epoch) float to a datetime.
    Helper used by the public num2date / num2timedelta pair."""
    return num2date(x, tz)


class _SwitchableDateConverter(DateConverter):
    """A converter that delegates to either the standard or concise
    converter depending on rcParams. Upstream uses this to honour the
    ``date.converter`` rcParam at runtime; here we just hold a flag."""

    _converter = 'auto'  # 'auto' | 'concise'

    @classmethod
    def use_concise(cls, b=True):
        cls._converter = 'concise' if b else 'auto'


def relativedelta(*args, **kwargs):
    """Thin wrapper that hands off to ``dateutil.relativedelta`` when
    available, falling back to a plain timedelta when not. Matches
    upstream's import (``from dateutil.relativedelta import relativedelta``)
    so user code that does ``from matplotlib.dates import relativedelta``
    still works.
    """
    try:
        from dateutil.relativedelta import relativedelta as _rd
        return _rd(*args, **kwargs)
    except Exception:
        import datetime as _dt
        # Fall back: convert known kwargs to a timedelta.
        days = kwargs.get('days', 0) + kwargs.get('weeks', 0) * 7
        return _dt.timedelta(days=days,
                             hours=kwargs.get('hours', 0),
                             minutes=kwargs.get('minutes', 0),
                             seconds=kwargs.get('seconds', 0))


# rrule is provided by dateutil. Re-export when available so upstream
# code can do ``from matplotlib.dates import rrule``.
try:
    from dateutil.rrule import rrule
except Exception:
    def rrule(*args, **kwargs):
        """Stub when dateutil isn't available — returns an empty iterator."""
        return iter([])


def date_ticker_factory(span, tz=None, numticks=5):
    """Pick a sensible :class:`DateLocator` / :class:`DateFormatter` pair
    for an interval of ``span`` days. Returns ``(locator, formatter)``.

    The thresholds match upstream's defaults: < 1 month → DayLocator,
    < 1 year → MonthLocator, otherwise YearLocator.
    """
    if span < 30:
        return DayLocator(tz=tz), DateFormatter('%b %d', tz=tz)
    if span < 365:
        return MonthLocator(tz=tz), DateFormatter('%b %Y', tz=tz)
    return YearLocator(tz=tz), DateFormatter('%Y', tz=tz)


# ─── Added: missing time-unit constants from upstream dates.py ─────


# All values derive trivially from `60 sec / minute`, `24 hr / day`,
# etc. They appear in calendar-arithmetic helpers throughout upstream.
HOURS_PER_DAY = 24
MIN_PER_HOUR = 60
SEC_PER_MIN = 60
MINUTES_PER_DAY = HOURS_PER_DAY * MIN_PER_HOUR
SECONDS_PER_DAY = MINUTES_PER_DAY * SEC_PER_MIN
SECONDS_PER_HOUR = MIN_PER_HOUR * SEC_PER_MIN
SECONDS_PER_MINUTE = SEC_PER_MIN
MUSECONDS_PER_DAY = SECONDS_PER_DAY * 1_000_000

# Days-per-period constants — DAYS_PER_MONTH is the long-term average.
DAYS_PER_WEEK = 7
DAYS_PER_MONTH = 30.4375  # 365.25 / 12
DAYS_PER_YEAR = 365.25
WEEKS_PER_MONTH = DAYS_PER_MONTH / DAYS_PER_WEEK
MONTHS_PER_YEAR = 12

# Upstream exposes one more helper.
RRULE_EPOCH = '1970-01-01T00:00:00'


def _from_ordinalf_np_vectorized(x, tz=None):
    """Vectorised ordinal→datetime converter. Returns a numpy array of
    ``datetime.datetime`` objects (one per entry of ``x``). The shim
    just maps :func:`num2date` over the input."""
    return _np.asarray([num2date(xi, tz) for xi in _np.atleast_1d(x)])


