SEC_PER_HOUR = SECONDS_PER_HOUR
SEC_PER_DAY  = SECONDS_PER_DAY
SEC_PER_WEEK = SEC_PER_DAY * DAYS_PER_WEEK

# Names of weekdays in upstream's canonical order (Mon..Sun).
WEEKDAYS = ('Monday', 'Tuesday', 'Wednesday', 'Thursday',
            'Friday', 'Saturday', 'Sunday')


# UTC timezone — used for date conversions.
try:
    from datetime import timezone as _tz
    UTC = _tz.utc
except Exception:
    UTC = None


class rrulewrapper:
    """Wrap a :class:`dateutil.rrule.rrule` so its bound parameters can
    be modified after construction. Mirrors upstream's class of the
    same name."""

    def __init__(self, freq, tzinfo=None, **kwargs):
        self._construct = dict(freq=freq, **kwargs)
        self._tzinfo = tzinfo
        self._rrule = None
        self._build()

    def _build(self):
        try:
            from dateutil.rrule import rrule as _rrule
            self._rrule = _rrule(**self._construct)
        except Exception:
            self._rrule = None

    def set(self, **kwargs):
        self._construct.update(kwargs)
        self._build()

    def __iter__(self):
        return iter(self._rrule or [])

    def __getattr__(self, name):
        if self._rrule is None:
            raise AttributeError(name)
        return getattr(self._rrule, name)


# ─── Added: DateLocator helpers ─────────────────────────────────────


def _dl_datalim_to_dt(self):
    return None, None
def _dl_viewlim_to_dt(self):
    return None, None
def _dl_hms0d(self):  return False
def _dl_nonsingular(self, vmin, vmax):
    if vmin == vmax: return vmin - 1, vmax + 1
    return vmin, vmax
def _dl_set_tzinfo(self, tz): self.tz = tz

DateLocator.datalim_to_dt = _dl_datalim_to_dt
DateLocator.viewlim_to_dt = _dl_viewlim_to_dt
DateLocator.hms0d         = _dl_hms0d
DateLocator.nonsingular   = _dl_nonsingular
DateLocator.set_tzinfo    = _dl_set_tzinfo


# ─── Added: DateConverter interface methods ─────────────────────────


def _dc_axisinfo(unit, axis):
    from matplotlib.units import AxisInfo
    return AxisInfo(majloc=AutoDateLocator(), majfmt=AutoDateFormatter(AutoDateLocator()),
                     label='date')

def _dc_default_units(x, axis):
    return None

def _dc_convert(value, unit, axis):
    if isinstance(value, (list, tuple)):
        return [date2num(v) for v in value]
    return date2num(value)

DateConverter.axisinfo      = staticmethod(_dc_axisinfo)
DateConverter.default_units = staticmethod(_dc_default_units)
DateConverter.convert       = staticmethod(_dc_convert)


